INSERT INTO `support_replies` (`id`, `ticket_id`, `sender_id`, `sender_role`, `sender_type`, `is_from_staff`, `message`, `created_at`, `attachment_url`, `attachment_name`) VALUES
(1, 1, 2, 'tenant', 'INSTITUTE_ADMIN', 0, 'The annual renewal invoice for the Pro plan shows a monthly billing cycle. Our account team expects the annual amount with the 10% enterprise discount applied. Please verify.', '2026-08-24 10:15:00', NULL, NULL),
(40, 19, 647, 'tenant', 'BRANCH_ADMIN', 0, 'The BenQ overhead projector in Classroom 102 has developed severe lamp flicker and sudden shut-offs during evening XI Science lectures. Additionally, the wall speaker AUX jack is disconnected. Evening batches are facing disruption. Requesting urgent vendor dispatch or replacement unit from central inventory.', '2026-10-12 14:15:00', NULL, NULL),
(41, 19, 637, 'staff', 'INSTITUTE_ADMIN', 1, 'Noted with priority. Our hardware AMC partner (Apex Solutions) has been assigned ticket AMC-8841 and technician Mahesh will visit Village Road branch tomorrow morning by 11:00 AM. Meanwhile, please utilize the standby portable Epson projector kept in Room 104.', '2026-10-12 16:40:00', NULL, NULL),
(42, 19, 647, 'tenant', 'BRANCH_ADMIN', 0, 'Received the portable unit from Room 104 and configured it for the morning batch. Awaiting technician arrival at 11 AM.', '2026-10-13 09:30:00', NULL, NULL),
(43, 20, 648, 'tenant', 'BRANCH_ADMIN', 0, 'Following the walk-in admission drive this weekend, Plaza branch has enrolled 14 new students across 10th Standard batches. We have run completely out of printed Physics & Chemistry Module-2 question banks and formula handbooks. Requesting immediate dispatch of 20 book sets from the central publication warehouse.', '2026-10-13 11:45:00', NULL, NULL),
(44, 21, 637, 'tenant', 'INSTITUTE_ADMIN', 0, 'We configured our Karix SMS gateway credentials and submitted the 2-way payment reminder template under Principal Entity ID 1101552390000. Outbound WhatsApp/SMS webhooks are throwing HTTP 422: \"Template ID not registered on DLT portal\". Kindly assist in syncing our registered sender header BIJUAC with the production telecom whitelist.', '2026-10-11 16:20:00', NULL, NULL),
(45, 21, 1, 'staff', 'SAAS_ADMIN', 1, 'Hello Biju Babu, we have reviewed your submission. The TRAI DLT header \"BIJUAC\" was awaiting sender ID mapping on the carrier exchange. Our telecoms ops team has completed the binding and verified message routing through the Airtel gateway. Please run a test SMS trigger from Settings > Notifications and let us know if test delivery succeeds.', '2026-10-12 10:15:00', NULL, NULL),
(46, 21, 637, 'tenant', 'INSTITUTE_ADMIN', 0, 'Thank you team, test SMS dispatched to my mobile number in 4 seconds with proper template variables. Testing batch triggers now.', '2026-10-12 11:05:00', NULL, NULL),
(47, 22, 637, 'tenant', 'INSTITUTE_ADMIN', 0, 'Our current media repository utilization has reached 91% (22.8 GB / 25 GB limit) following the upload of handwritten answer sheets for 8th and 9th standard mid-term exams. In accordance with our active Enterprise SaaS subscription terms, kindly increase our institution\'s storage quota to 50 GB.', '2026-10-13 12:10:00', NULL, NULL);
INSERT INTO `support_tickets` (`id`, `ticket_number`, `tenant_id`, `branch_id`, `channel`, `subject`, `description`, `status`, `created_by`, `created_at`, `updated_at`) VALUES
(1, 'TKT-1001', 2, NULL, 'SAAS_SUPPORT', 'Invoice billing cycle mismatch on renewal', 'The annual renewal invoice for the Pro plan shows a monthly billing cycle. Our account team expects the annual amount with the 10% enterprise discount applied. Please verify.', 'In Progress', 2, '2026-08-24 10:15:00', '2026-09-02 15:43:04'),
(19, 'TKT-1002', 18, 4, 'INSTITUTE_SUPPORT', 'Classroom 102 Ceiling Projector & Audio Setup Failure', 'The BenQ overhead projector in Classroom 102 has developed severe lamp flicker and sudden shut-offs during evening XI Science lectures. Additionally, the wall speaker AUX jack is disconnected. Evening batches are facing disruption. Requesting urgent vendor dispatch or replacement unit from central inventory.', 'In Progress', 647, '2026-10-12 14:15:00', '2026-10-12 14:15:00'),
(20, 'TKT-1003', 18, 5, 'INSTITUTE_SUPPORT', 'Urgent Shortage of 10th Standard Science Prelim Workbooks (Module 2)', 'Following the walk-in admission drive this weekend, Plaza branch has enrolled 14 new students across 10th Standard batches. We have run completely out of printed Physics & Chemistry Module-2 question banks and formula handbooks. Requesting immediate dispatch of 20 book sets from the central publication warehouse.', 'Open', 648, '2026-10-13 11:45:00', '2026-10-13 11:45:00'),
(21, 'TKT-1004', 18, NULL, 'SAAS_SUPPORT', 'DLT SMS Header & Template Approval Delay for Fee Due Alerts', 'We configured our Karix SMS gateway credentials and submitted the 2-way payment reminder template under Principal Entity ID 1101552390000. Outbound WhatsApp/SMS webhooks are throwing HTTP 422: \"Template ID not registered on DLT portal\". Kindly assist in syncing our registered sender header BIJUAC with the production telecom whitelist.', 'In Progress', 637, '2026-10-11 16:20:00', '2026-10-11 16:20:00'),
(22, 'TKT-1005', 18, NULL, 'SAAS_SUPPORT', 'Cloud Storage Limit Upgrade for Scanned Exam Answer Sheets & Study Material', 'Our current media repository utilization has reached 91% (22.8 GB / 25 GB limit) following the upload of handwritten answer sheets for 8th and 9th standard mid-term exams. In accordance with our active Enterprise SaaS subscription terms, kindly increase our institution\'s storage quota to 50 GB.', 'Open', 637, '2026-10-13 12:10:00', '2026-10-13 12:10:00');
